// ─────────────────────────────────────────────────────────────────────────────
// Format Response
// Parses AI Agent output for text and images, and reads exact token usage metrics
// directly from OpenRouter's raw API response (Fetch OpenRouter Usage Payload).
// ─────────────────────────────────────────────────────────────────────────────

let agentOutput = {};
try {
  agentOutput = $('AI Agent').item.json || {};
} catch (e) {
  agentOutput = {};
}

const raw = String(agentOutput.output || agentOutput.replyText || $('Fetch OpenRouter Usage Payload').item.json.choices?.[0]?.message?.content || '');
const imgs = [];
const re = /\[IMG\]\s*(\S+)/g;
let m;
while ((m = re.exec(raw)) !== null) { imgs.push(m[1]); }
const replyText = raw.replace(/\[IMG\]\s*\S+/g, '').replace(/\n{3,}/g, '\n\n').trim();

// Read raw OpenRouter usage object directly from HTTP Request node response
const httpPayload = $('Fetch OpenRouter Usage Payload').item.json || {};
const usage = httpPayload.usage || {};

const promptTokens = Number(usage.prompt_tokens ?? usage.promptTokens ?? 0);
const completionTokens = Number(usage.completion_tokens ?? usage.completionTokens ?? 0);
const totalTokens = Number(usage.total_tokens ?? usage.totalTokens ?? (promptTokens + completionTokens));

const modelId = String(
  $('When Called by Platform').item.json.model ||
  $('Fetch Bot Config').item.json.model ||
  httpPayload.model ||
  'anthropic/claude-3.5-sonnet'
);

let costUsd = Number(usage.cost ?? usage.cost_usd ?? usage.costUsd ?? 0);

if (!costUsd || costUsd <= 0) {
  let pRate = 3.0;   // $/1M prompt tokens
  let cRate = 15.0;  // $/1M completion tokens

  const lower = modelId.toLowerCase();
  if (lower.includes('claude-3.5-sonnet') || lower.includes('claude-sonnet') || lower.includes('gpt-4o') || lower.includes('deepseek-r1') || lower.includes('o1-preview')) {
    pRate = 3.0; cRate = 15.0;
  } else if (lower.includes('flash') || lower.includes('llama') || lower.includes('gemma') || lower.includes('deepseek-chat')) {
    pRate = 0.075; cRate = 0.30;
  } else {
    pRate = 0.50; cRate = 1.50;
  }

  costUsd = Number(
    ((promptTokens * pRate / 1_000_000) +
     (completionTokens * cRate / 1_000_000)).toFixed(6)
  );
}

const costBdt = Number((costUsd * 120).toFixed(4));

return [{
  json: {
    replyText,
    galleryImages: imgs,
    promptTokens,
    completionTokens,
    totalTokens,
    costUsd,
    costBdt
  }
}];

